result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "tlv.py", "content": """"TLV (tag-length-value) codec modeled on DER structure.

Encoding rules
--------------
Tag (1 byte):
    bit 5 (0x20) : constructed flag
    bits 4..0    : tag number (0..31)

Length (definite form only):
    < 128        : short form, single byte
    <= 255       : 0x81 followed by 1 length byte
    <= 65535     : 0x82 followed by 2 length bytes (big-endian)

Value:
    primitive    : raw payload bytes
    constructed  : concatenation of encoded child TLVs

Node representation:
    ('prim', tag, payload_bytes)
    ('cons', tag, [children])
"""

from __future__ import annotations

CONSTRUCTED_FLAG = 0x20
MAX_TAG_NUMBER = 31


class TLVError(ValueError):
    """Base class for all TLV decoding errors."""


class InvalidTagError(TLVError):
    pass


class TrailingGarbageError(TLVError):
    pass


class TruncatedValueError(TLVError):
    pass


class ChildOverrunError(TLVError):
    pass


class EmptyInputError(TLVError):
    pass


# ---------------------------------------------------------------------------
# Encoding
# ---------------------------------------------------------------------------

def _encode_length(n: int) -> bytes:
    if n < 0:
        raise ValueError("length must be non-negative")
    if n < 128:
        return bytes([n])
    if n <= 0xFF:
        return bytes([0x81, n])
    if n <= 0xFFFF:
        return bytes([0x82, (n >> 8) & 0xFF, n & 0xFF])
    raise ValueError(f"length {n} exceeds 2-byte long form maximum")


def _encode_node(node, out: bytearray) -> None:
    try:
        kind, tag, body = node
    except (TypeError, ValueError):
        raise ValueError(f"malformed node, expected ('prim'|'cons', tag, value): {node!r}")
    if not isinstance(tag, int) or not (0 <= tag <= MAX_TAG_NUMBER):
        raise ValueError(f"tag number must be an integer in 0..{MAX_TAG_NUMBER}, got {tag!r}")

    if kind == 'prim':
        if isinstance(body, (bytearray, memoryview)):
            body = bytes(body)
        if not isinstance(body, bytes):
            raise ValueError(f"primitive payload must be bytes, got {type(body).__name__}")
        header = bytes([tag])
        out += header
        out += _encode_length(len(body))
        out += body
    elif kind == 'cons':
        if not isinstance(body, (list, tuple)):
            raise ValueError(
                f"constructed children must be a list/tuple, got {type(body).__name__}"
            )
        children = bytearray()
        for child in body:
            _encode_node(child, children)
        out += bytes([tag | CONSTRUCTED_FLAG])
        out += _encode_length(len(children))
        out += children
    else:
        raise ValueError(f"unknown node kind {kind!r}, expected 'prim' or 'cons'")


def encode(node) -> bytes:
    """Encode a node tree into TLV bytes."""
    out = bytearray()
    _encode_node(node, out)
    return bytes(out)


# ---------------------------------------------------------------------------
# Decoding
# ---------------------------------------------------------------------------

def _read_tag(data: bytes, off: int) -> tuple[int, bool]:
    """Return (tag_number, constructed)."""
    b = data[off]
    if b & 0xC0:
        raise InvalidTagError(
            f"invalid tag byte 0x{b:02x} at offset {off}: reserved high bits set"
        )
    return b & 0x1F, bool(b & CONSTRUCTED_FLAG)


def _read_length(data: bytes, off: int, end: int) -> tuple[int, int]:
    """Return (length_value, offset_after_length_bytes)."""
    first = data[off]
    if first < 128:
        return first, off + 1
    if first == 0x81:
        if off + 1 >= end:
            raise TruncatedValueError(
                f"truncated length at offset {off}: 0x81 prefix missing its length byte"
            )
        return data[off + 1], off + 2
    if first == 0x82:
        if off + 2 >= end:
            raise TruncatedValueError(
                f"truncated length at offset {off}: 0x82 prefix missing length byte(s)"
            )
        return (data[off + 1] << 8) | data[off + 2], off + 3
    raise InvalidTagError(
        f"invalid length byte 0x{first:02x} at offset {off}: "
        f"only definite forms supported (short, 0x81, 0x82)"
    )


def _decode_at(data: bytes, off: int, end: int, parent_end: int | None):
    """Decode one TLV starting at `off`, which must not extend past `end`.

    If this element is a child inside a constructed parent bounded by
    `parent_end`, a value extending past that bound raises ChildOverrunError;
    otherwise an overrun of the outer buffer raises TruncatedValueError.
    """
    if off >= end:
        raise TruncatedValueError(f"truncated element at offset {off}: missing tag byte")

    tag, constructed = _read_tag(data, off)
    if off + 1 >= end:
        raise TruncatedValueError(f"truncated element at offset {off}: missing length byte")
    length, val_off = _read_length(data, off + 1, end)
    val_end = val_off + length

    def bounds_error(exc_cls, label):
        limit = f"parent ends at {parent_end}" if parent_end is not None else f"data ends at {end}"
        return exc_cls(
            f"{label} at offset {off}: value needs bytes [{val_off}, {val_end}) "
            f"but {limit}"
        )

    if parent_end is not None and val_end > parent_end:
        raise bounds_error(ChildOverrunError, "child overruns its parent")
    if val_end > end:
        raise bounds_error(TruncatedValueError, "truncated value")

    if constructed:
        children = []
        cur = val_off
        while cur < val_end:
            child, cur = _decode_at(data, cur, val_end, val_end)
            children.append(child)
        return ('cons', tag, children), val_end

    return ('prim', tag, bytes(data[val_off:val_end])), val_end


def decode(data) -> tuple:
    """Decode a complete TLV byte string into a single node tree.

    Raises TLVError subclasses (with byte offsets in their messages) on any
    malformation: trailing garbage, truncated values, children overrunning
    their parent, invalid tags/lengths, or empty input.
    """
    if isinstance(data, (bytearray, memoryview)):
        data = bytes(data)
    if not isinstance(data, bytes):
        raise TypeError(f"expected bytes, got {type(data).__name__}")
    if len(data) == 0:
        raise EmptyInputError("cannot decode empty input at offset 0")

    node, consumed = _decode_at(data, 0, len(data), None)
    if consumed != len(data):
        raise TrailingGarbageError(
            f"trailing garbage after TLV element ending at offset {consumed}: "
            f"{len(data) - consumed} unexpected byte(s) starting at offset {consumed}"
        )
    return node
